+import { ConfigParseError } from "./errors.ts";
+import type { ConfigOptions } from "./types.ts";
+
+function camelCase(value: string): string {
+  return value.replace(/-([a-zA-Z0-9])/g, (_, char) => char.toUpperCase());
+}
+
+function flatten(value: Record<string, unknown>, prefix = ""): Record<string, unknown> {
+  const result: Record<string, unknown> = {};
+  for (const [key, item] of Object.entries(value)) {
+    const name = prefix ? `${prefix}.${camelCase(key)}` : camelCase(key);
+    if (isPlainObject(item)) {
+      Object.assign(result, flatten(item, name));
+    } else {
+      result[name] = item;
+    }
+  }
+  return result;
+}
+
+export function isPlainObject(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null && !Array.isArray(value) &&
+    (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
+}
+
+function parseRc(content: string): Record<string, unknown> {
+  const result: Record<string, unknown> = {};
+  for (const line of content.split(/\\r?\
/)) {
+    const trimmed = line.trim();
+    if (!trimmed || trimmed.startsWith("#")) continue;
+    const equals = trimmed.indexOf("=");
+    if (equals === -1) throw new Error("Expected key=value pair.");
+    const key = camelCase(trimmed.slice(0, equals).trim());
+    let value = trimmed.slice(equals + 1).trim();
+    if (value.startsWith('"') && value.endsWith('"') && value.length >= 2) {
+      value = value.slice(1, -1);
+    } else if (value === "true" || value === "false") {
+      result[key] = value === "true";
+      continue;
+    } else if (/^-?(?:\\d+\\.?\\d*|\\.\\d+)$/.test(value)) {
+      result[key] = Number(value);
+      continue;
+    }
+    result[key] = value;
+  }
+  return result;
+}
+
+async function readFile(path: string): Promise<string> {
+  // dnt-shim-ignore
+  const { Deno } = globalThis as any;
+  if (Deno) return await Deno.readTextFile(path);
+  const fs = await import("node:fs/promises");
+  return await fs.readFile(path, "utf8");
+}
+
+async function resolve(path: string): Promise<string> {
+  // dnt-shim-ignore
+  const { Deno, process } = globalThis as any;
+  if (Deno) return Deno.realPath(path);
+  const nodePath = await import("node:path");
+  return nodePath.resolve(process.cwd(), path);
+}
+
+function cwd(): string {
+  // dnt-shim-ignore
+  const { Deno, process } = globalThis as any;
+  return Deno ? Deno.cwd() : process.cwd();
+}
+
+async function join(...parts: string[]): Promise<string> {
+  const nodePath = await import("node:path");
+  return nodePath.join(...parts);
+}
+
+function filename(name: string, format: string): string {
+  return format === ".rc" ? `.${name}rc` : `${name}${format}`;
+}
+
+export async function loadConfig(options: ConfigOptions): Promise<{
+  path?: string;
+  values: Record<string, unknown>;
+}> {
+  const paths = options.searchPaths?.length ? options.searchPaths : [cwd()];
+  const formats = options.formats?.length ? options.formats : [".json", ".rc"];
+  let path: string | undefined;
+  const values: Record<string, unknown> = {};
+
+  for (const searchPath of paths) {
+    for (const format of formats) {
+      const candidate = await join(searchPath, filename(options.name, format));
+      let content: string;
+      try {
+        content = await readFile(candidate);
+      } catch (error: unknown) {
+        if ((error as { code?: string }).code === "ENOENT" || error instanceof Deno.errors.NotFound) continue;
+        throw error;
+      }
+      const resolved = await resolve(candidate);
+      let parsed: Record<string, unknown>;
+      try {
+        const value = options.parser
+          ? options.parser(content)
+          : format === ".rc" ? parseRc(content) : JSON.parse(content);
+        if (!isPlainObject(value)) throw new Error("Configuration must be a plain object.");
+        parsed = flatten(value);
+      } catch (error) {
+        throw new ConfigParseError(resolved, error);
+      }
+      path ??= resolved;
+      for (const [key, value] of Object.entries(parsed)) {
+        if (typeof values[key] === "undefined") values[key] = value;
+      }
+      if (!options.mergeConfigs) return { path, values };
+    }
+  }
+  return { path, values };
+}
